namespace Simulador.Teorico;

/// <summary>
/// FAQ estático do nível Teórico: perguntas prontas com respostas prontas, escritas à mão para cada questão.
/// A pergunta "Por que as outras alternativas estão erradas?" é montada pelo serviço a partir da explicação
/// estruturada da questão, para nunca divergir do gabarito.
/// </summary>
internal static class PerguntasPadrao
{
    private const string PEx = "Dê um exemplo do dia a dia.";
    private const string PMn = "Como lembrar disso na prova?";
    private const string PEr = "Qual é o erro mais comum?";

    private static (string Pergunta, string Resposta) Ex(string r) => (PEx, r);
    private static (string Pergunta, string Resposta) Mn(string r) => (PMn, r);
    private static (string Pergunta, string Resposta) Er(string r) => (PEr, r);

    /// <summary>Perguntas escritas à mão, por id de questão (duas por questão).</summary>
    public static IReadOnlyDictionary<string, IReadOnlyList<(string Pergunta, string Resposta)>> Criar() =>
        new Dictionary<string, IReadOnlyList<(string Pergunta, string Resposta)>>(StringComparer.Ordinal)
        {
            // ===== Acesso e contas =====
            ["ac-01"] = [Ex("Alguém liga dizendo ser da diretoria e pede a senha nova pelo chat. Você pede matrícula e ramal do cadastro antes de qualquer reset, mesmo que a pessoa tenha pressa."), Mn("Identidade primeiro, credencial depois: nenhum reset sai sem confirmar quem pediu.")],
            ["ac-02"] = [Er("Achar que trocar a senha todo mês deixa a conta mais segura. As diretrizes do NIST apontam o contrário: a troca forçada gera variações previsíveis, como Senha1 e Senha2."), Mn("Pense em longa e verificada: comprimento e checagem contra vazamentos valem mais que troca frequente.")],
            ["ac-03"] = [Ex("Entrar no sistema com a senha e depois digitar o código de seis dígitos do aplicativo autenticador do celular. São dois fatores de categorias diferentes: o que você sabe e o que você possui."), Er("Contar dois itens do mesmo tipo como MFA, por exemplo senha mais PIN ou senha mais pergunta secreta. Os dois são algo que você sabe.")],
            ["ac-04"] = [Ex("Uma funcionária trocou a senha, mas o celular antigo continua tentando entrar com a anterior e bloqueia a conta toda manhã. Olhar a origem das tentativas mostra o aparelho."), Mn("Desbloquear sem investigar é remédio sem diagnóstico: veja de onde vêm as tentativas.")],
            ["ac-05"] = [Ex("O estagiário entra no grupo Financeiro-Relatorios-Leitura, que só lê a pasta Relatórios. Quando o estágio acaba, basta tirá-lo do grupo."), Mn("Menor privilégio: só o que precisa, só onde precisa, concedido por grupo.")],
            ["ac-06"] = [Er("Lembrar de desativar a conta e esquecer das sessões, dos tokens e dos acessos a aplicativos externos, que podem continuar válidos depois do desligamento."), Ex("No desligamento do colaborador, a conta é desativada, as sessões são revogadas e a caixa de e-mail passa ao gestor conforme a política de retenção.")],
            ["ac-07"] = [Mn("Negar vence permitir. Se há uma negação explícita em qualquer grupo do usuário, ela prevalece."), Er("Achar que a permissão de um grupo compensa a negação de outro. Não compensa: a negação explícita tem precedência.")],
            ["ac-08"] = [Ex("Chega um e-mail do suposto diretor, às 18h, pedindo o reset da conta de administrador para fechar um contrato hoje. Você liga para o ramal oficial dele e abre o chamado pelo processo."), Mn("Urgência mais autoridade é o par clássico da engenharia social. Desconfie e valide por outro canal.")],
            ["ac-09"] = [Ex("Com SSO, a pessoa entra uma vez no portal da empresa e abre ERP, e-mail e intranet sem digitar senha de novo. Ao ser desligada, um único bloqueio corta tudo."), Er("Achar que o SSO dispensa o MFA. O ideal é proteger o provedor de identidade com MFA, pois ele passa a ser a porta de entrada para tudo.")],
            ["ac-10"] = [Ex("A conta que roda o backup noturno usa senha longa guardada em cofre, tem permissão apenas para ler os dados e não aceita login interativo."), Er("Colocar a senha da conta de serviço no código ou em um arquivo de configuração versionado. Ela acaba em repositórios, cópias e backups.")],
            ["ac-11"] = [Ex("Em vez de repetir a mesma senha em tudo, a pessoa guarda uma senha longa e diferente para cada sistema no gerenciador e memoriza só a senha mestra, protegida por MFA."), Er("Reaproveitar a mesma senha em vários sistemas. Quando um deles vaza, todos os outros ficam expostos.")],
            ["ac-12"] = [Mn("Conta nova: perfil do cargo, aprovação do gestor e senha temporária que obriga a troca."), Er("Dar privilégio alto para evitar chamados ou deixar o novato usar a conta de um colega, o que apaga a rastreabilidade.")],
            ["ac-13"] = [Ex("Em vez de dar acesso a 30 pessoas uma a uma, você as coloca no grupo Compras. Quando alguém sai da área, basta tirá-lo do grupo."), Mn("A permissão vai para o grupo e as pessoas vão para o grupo.")],
            ["ac-14"] = [Mn("Notificação de MFA que você não pediu significa que alguém já tem sua senha. Negue, troque a senha e reporte."), Er("Aprovar uma notificação só para parar o incômodo. Esse é o ataque de fadiga de MFA: o invasor insiste até alguém aprovar.")],
            ["ac-15"] = [Ex("Uma analista sai do Financeiro para Compras. Ela perde o acesso aos pagamentos e ganha o acesso aos pedidos de compra, conforme a aprovação do novo gestor."), Er("Somar acessos novos sem remover os antigos. Com o tempo a pessoa acumula privilégios que não deveria ter.")],
            ["ac-16"] = [Mn("Para administradores: duas contas (uma de uso comum e outra privilegiada) e MFA nas privilegiadas."), Er("Usar a conta de administrador para ler e-mail e navegar. Um clique em phishing entrega privilégio máximo ao atacante.")],
            ["ac-17"] = [Mn("Pela rede, vale o mais restritivo entre o compartilhamento e o NTFS."), Er("Achar que o Controle total do NTFS prevalece sobre uma permissão de compartilhamento mais restrita. Pela rede, o menor nível é o que vale.")],
            ["ac-18"] = [Ex("A cada trimestre o gestor recebe a lista de acessos da equipe e confirma ou remove cada item. O acesso de um projeto encerrado é revogado."), Mn("Recertificação é a pergunta você ainda precisa disso?, feita de tempos em tempos.")],
            ["ac-19"] = [Mn("Resistente a phishing: a chave FIDO2 só responde ao site legítimo, então uma página falsa não consegue o segundo fator."), Er("Achar que SMS e e-mail são tão fortes quanto uma chave física. Códigos digitados podem ser entregues a um site falso.")],
            ["ac-20"] = [Mn("Log de acesso privilegiado registra quem, quando e o quê. Nunca a senha."), Ex("Se um administrador apaga um grupo, o registro mostra o usuário, o horário e o grupo afetado, sem guardar a senha usada.")],

            // ===== Redes =====
            ["re-01"] = [Mn("169.254 quer dizer que ninguém deu IP. Pense na APIPA como o plano B do Windows quando o DHCP não responde."), Ex("Um notebook ligado em uma tomada nova mostra 169.254.x.x e não acessa nada. O cabo está bom, mas a porta não está na VLAN que tem DHCP.")],
            ["re-02"] = [Mn("Ping por IP funciona e por nome não? Suspeite do DNS. A rede está viva, só falta traduzir o nome."), Ex("Você acessa 10.0.0.20 e o sistema abre, mas erp.aurora.local não abre. O servidor está bem e a resolução de nomes é que falha.")],
            ["re-03"] = [Mn("Decore as três faixas privadas: 10.x.x.x, 172.16 a 172.31 e 192.168.x.x."), Er("Achar que todo 172.x é privado. Só vai de 172.16.0.0 a 172.31.255.255. De 172.32 em diante é público.")],
            ["re-04"] = [Mn("Hosts são 2 elevado ao número de bits de host, menos 2. Em uma /24, 2 elevado a 8 menos 2 dá 254."), Er("Esquecer de descontar os endereços de rede e de broadcast e responder 256.")],
            ["re-05"] = [Ex("O PC da contabilidade (VLAN 10) precisa acessar a impressora do térreo (VLAN 20). O switch de camada 3 ou o roteador faz o roteamento entre as duas."), Mn("VLAN separa e roteador junta. Sem camada 3, VLANs diferentes não conversam.")],
            ["re-06"] = [Er("Concluir que há falha só porque um salto mostra asteriscos. Se os saltos seguintes respondem, o tráfego passa. O equipamento apenas não responde ao ICMP."), Mn("Olhe o destino, não só os intermediários: asteriscos no meio com resposta no fim é comum.")],
            ["re-07"] = [Mn("HTTPS tem S de seguro e porta 443. HTTP puro é 80, SSH é 22 e SMTP é 25."), Ex("Ao digitar https://portal.aurora.local o navegador conecta na porta 443 sem você precisar escrever o número.")],
            ["re-08"] = [Ex("No Wi-Fi o celular abre sites externos, mas a intranet não resolve, porque o DHCP daquele SSID entrega um DNS público em vez do DNS interno."), Mn("Resolve fora, mas não dentro? Veja qual DNS o DHCP entregou.")],
            ["re-09"] = [Ex("O técnico fixa o 192.168.1.50 em uma impressora, mas o DHCP também distribui esse endereço a um notebook. São dois equipamentos com o mesmo IP, e ambos perdem rede."), Mn("IP fixo dentro do escopo gera conflito. Fixe fora do intervalo ou crie uma reserva no DHCP.")],
            ["re-10"] = [Mn("Camadas de baixo para cima: cabo e luzes, depois IP e gateway, depois DNS e, por último, o aplicativo."), Er("Começar reinstalando o aplicativo. Se a causa for cabo ou DNS, o tempo é perdido e a causa real fica escondida.")],
            ["re-11"] = [Ex("O PC 192.168.1.50 acessa um site externo. Como o destino é de outra rede, o pacote vai ao gateway (192.168.1.1), que o encaminha."), Mn("Gateway é a porta de saída da rede local.")],
            ["re-12"] = [Mn("ipconfig mostra a rede. ipconfig /all mostra tudo, incluindo DNS e DHCP."), Ex("O usuário sem rede abre o prompt, roda ipconfig e vê 169.254.x.x: a placa não recebeu IP do DHCP.")],
            ["re-13"] = [Mn("A de Address: associa o nome a um endereço IPv4. MX é e-mail, CNAME é apelido e PTR é consulta reversa."), Er("Confundir CNAME com A. O CNAME aponta para outro nome, não para um IP.")],
            ["re-14"] = [Mn("A /26 deixa 6 bits de host: 2 elevado a 6 dá 64 endereços, menos 2 dá 62 hosts. Na máscara, o último número é 192."), Er("Responder 64 hosts e esquecer os endereços de rede e de broadcast.")],
            ["re-15"] = [Ex("O IP do servidor mudou às 10h, mas o TTL do registro era de 24 horas. Quem consultou antes continua no endereço antigo até o cache expirar."), Mn("Mudou o IP e alguns ainda vão ao antigo? Pense em cache DNS e TTL. Antes de uma mudança planejada, reduza o TTL com antecedência.")],
            ["re-16"] = [Mn("Caminho é tracert. Nomes é nslookup."), Ex("O site não abre. O nslookup mostra se o nome vira IP e o tracert mostra por onde o tráfego passa até o destino.")],
            ["re-17"] = [Mn("NAT: muitos IPs privados atrás de um IP público."), Ex("Dezenas de PCs com 192.168.x.x navegam usando o mesmo IP público do roteador da empresa. O NAT mantém a tabela de quem pediu o quê.")],
            ["re-18"] = [Er("Mandar o usuário ignorar o aviso e continuar. Isso acostuma as pessoas a aceitar certificados inválidos e abre espaço para interceptação."), Mn("Erro de certificado: veja a validade, se o emissor é confiável e se o nome do certificado é igual ao endereço acessado.")],
            ["re-19"] = [Mn("Telnet envia tudo em texto claro. SSH é o shell seguro, com cifra."), Er("Manter o Telnet em equipamentos de rede porque sempre funcionou. Qualquer pessoa que capture o tráfego lê a senha.")],
            ["re-20"] = [Mn("O DNS interno sem encaminhador só conhece o que é dele. Configure forwarders para o resto."), Ex("O DNS do Windows Server responde aurora.local, mas não os sites externos. Aponta-se um forwarder para o DNS do provedor, e os nomes externos passam a resolver.")],

            // ===== Hardware =====
            ["ha-01"] = [Mn("Nenhuma luz? Energia primeiro: cabo, tomada, filtro de linha e chave da fonte."), Er("Trocar peças caras, como placa de vídeo ou fonte, antes de testar a tomada e o cabo de força.")],
            ["ha-02"] = [Ex("Um HD de cinco anos começa a fazer tic-tic e trava. Você copia as pastas do usuário para um disco externo antes de qualquer outra coisa."), Er("Tentar formatar ou consertar o disco antes de copiar os dados. Cada uso a mais pode piorar a falha.")],
            ["ha-03"] = [Mn("RAM cheia significa disco trabalhando muito (paginação) e tudo lento."), Ex("A estação com 4 GB abre o ERP, três planilhas e o navegador. A luz do disco não para e o sistema trava, porque a memória acabou.")],
            ["ha-04"] = [Mn("SSD é sem peças móveis, com acesso rápido e mais resistente a impacto. Mas ainda precisa de backup."), Er("Achar que SSD dispensa backup. Ele também falha, e a falha pode ser súbita.")],
            ["ha-05"] = [Mn("RAID 1 é espelho: protege contra falha de disco, não contra erro humano nem ransomware."), Er("Tratar RAID como backup. Se um arquivo é apagado ou criptografado, os dois discos refletem a mesma perda.")],
            ["ha-06"] = [Ex("O PC dá bipes ao ligar e não inicia. Você consulta o manual da placa-mãe, que explica o padrão de bipes daquele fabricante de BIOS, e descobre qual componente verificar."), Mn("Bipe é código. O significado depende do fabricante da BIOS, então leia o manual.")],
            ["ha-07"] = [Ex("Um notebook de três anos cheio de poeira desliga ao abrir planilhas pesadas. Depois de limpar o cooler e trocar a pasta térmica, ele deixa de desligar."), Mn("Calor demais e desligamento sozinho: limpe a ventilação e renove a pasta térmica.")],
            ["ha-08"] = [Mn("Setores realocados crescendo significa disco morrendo. Backup agora e troca planejada."), Er("Ignorar o alerta SMART porque o disco ainda funciona. Realocações em alta costumam anteceder a falha.")],
            ["ha-09"] = [Ex("Falta luz às 14h. O nobreak mantém o servidor por alguns minutos, tempo para o desligamento seguro ou para o gerador entrar."), Er("Achar que o nobreak mantém o servidor ligado por horas. Ele cobre minutos. Para mais tempo é preciso gerador.")],
            ["ha-10"] = [Mn("Desligar, desconectar e descarregar: sem energia e sem estática."), Ex("Antes de trocar a memória, você desliga, tira o cabo de força, toca em uma parte metálica do gabinete ou usa pulseira antiestática, e só então abre.")],
            ["ha-11"] = [Ex("Um documento travado bloqueia a fila. Você cancela os trabalhos, reinicia o serviço Spooler de impressão e envia uma página de teste."), Mn("Impressora não imprime? Fila e spooler antes de trocar o equipamento.")],
            ["ha-12"] = [Mn("A RAM é a mesa de trabalho: rápida, mas some quando desliga. O disco é o armário."), Er("Confundir RAM com armazenamento. Abrir mais programas esgota a RAM, não o espaço em disco.")],
            ["ha-13"] = [Mn("Tela preta: comece pelo cabo e pela entrada de vídeo do monitor."), Er("Concluir que o sistema operacional está corrompido sem testar outro cabo ou outro monitor.")],
            ["ha-14"] = [Mn("RAID 0 é zero redundância: mais velocidade, mas se um disco falha, tudo se perde."), Er("Escolher RAID 0 para dados importantes. A velocidade vem à custa de não suportar nenhuma falha.")],
            ["ha-15"] = [Ex("Depois de uma queda de energia, o PC não acha o disco de boot. Na BIOS ou UEFI o disco não aparece, o que sugere cabo solto ou disco com defeito."), Mn("Sem boot: a BIOS ou UEFI mostra o disco? A ordem de inicialização está certa?")],
            ["ha-16"] = [Mn("Notebook: ventilação livre e bateria sem calor nem descarga total."), Er("Usar o notebook sobre cama ou sofá, que bloqueiam as entradas de ar e esquentam o equipamento.")],
            ["ha-17"] = [Mn("O RAID 5 gasta um disco com paridade: capacidade é (N menos 1) vezes o tamanho do disco."), Er("Somar todos os discos e esquecer a paridade.")],
            ["ha-18"] = [Ex("Depois de adicionar dois pentes, o PC dá tela azul. Ao rodar o MemTest86, um dos pentes acusa erros, e retirá-lo resolve."), Mn("Memória nova com tela azul: teste com ferramenta e isole pente a pente.")],
            ["ha-19"] = [Mn("Online é dupla conversão, sempre pelo inversor e sem tempo de transferência. Offline usa a rede direto e a bateria só na falta."), Er("Achar que todo nobreak protege igual. O offline tem um curto tempo de transferência e condiciona menos a energia.")],
            ["ha-20"] = [Mn("Disco falho em RAID: identifique o disco certo, confirme o backup e acompanhe a reconstrução."), Er("Remover o disco errado. Em um RAID 5 isso derruba o volume, pois já falta um disco.")],

            // ===== Sistemas e ERP =====
            ["si-01"] = [Ex("Quando o comercial lança um pedido, o estoque reserva o item e o financeiro gera a cobrança, tudo na mesma base. É o ERP integrando os módulos."), Mn("ERP é um sistema, uma base e vários módulos.")],
            ["si-02"] = [Mn("Mensagem, módulo, horário e passos: com esses quatro dados dá para reproduzir o erro e achar o log."), Er("Registrar só ERP com erro. Sem a mensagem exata e os passos, ninguém consegue reproduzir o problema.")],
            ["si-03"] = [Ex("A atualização do ERP é marcada para sábado à noite, comunicada na quarta, com backup e plano de retorno prontos."), Er("Atualizar em horário de pico ou de fechamento por ser mais prático. Se falhar, o impacto no negócio é máximo.")],
            ["si-04"] = [Mn("Homologação é o ensaio geral: testa-se ali antes de ir para a produção."), Ex("O novo cálculo de impostos é testado em homologação com dados fictícios. Só depois de aprovado vai para a produção.")],
            ["si-05"] = [Mn("Lentidão em hora fixa lembra concorrência: olhe conexões, bloqueios e consultas pesadas naquele horário."), Ex("Às 9h todos entram e rodam relatórios. O banco atinge o limite de conexões e o ERP trava. O registro de consultas lentas mostra o relatório culpado.")],
            ["si-06"] = [Mn("A chave primária é o RG da linha: única e identifica o registro."), Er("Confundir chave primária com ordenação ou com índice de busca. A chave garante unicidade. Ordenar é função da consulta.")],
            ["si-07"] = [Mn("401 é não autorizado (credencial). 403 é proibido. 404 é não encontrado."), Ex("A senha da conta de serviço da loja virtual foi trocada, mas a integração segue com a antiga. Toda chamada volta 401 até a credencial ser atualizada.")],
            ["si-08"] = [Ex("Uma transferência entre contas debita a origem e credita o destino. Se o crédito falhar, a transação desfaz o débito e nada fica pela metade."), Mn("O A de ACID é atomicidade: tudo ou nada.")],
            ["si-09"] = [Ex("A transação 1 bloqueou a linha do cliente e quer a do pedido. A transação 2 bloqueou o pedido e quer a do cliente. Cada uma espera a outra e o banco aborta uma delas."), Mn("Deadlock é um abraço de espera: A espera B e B espera A.")],
            ["si-10"] = [Er("Aplicar a mudança direto em produção, rapidinho, sem aprovação e sem plano de retorno."), Mn("Mudança segura tem registro, aprovação, teste e caminho de volta.")],
            ["si-11"] = [Ex("Na migração do módulo de compras, a analista da área valida com a TI se as regras de aprovação e os relatórios estão certos antes da virada."), Mn("Usuário-chave é a ponte entre o negócio e a TI.")],
            ["si-12"] = [Mn("Chamado bom responde: o que fez, onde (tela) e qual mensagem apareceu."), Er("Aceitar não funciona como descrição. Sem detalhes, o chamado volta várias vezes para o solicitante.")],
            ["si-13"] = [Mn("SELECT lê, INSERT cria, UPDATE altera e DELETE remove."), Ex("SELECT nome, saldo FROM clientes WHERE id = 10 consulta o cliente 10 sem alterar nada.")],
            ["si-14"] = [Mn("DELETE tira linhas. DROP tira a tabela."), Er("Rodar DELETE sem WHERE achando que apaga uma linha só. Ele apaga todas as linhas da tabela.")],
            ["si-15"] = [Ex("Quem lança notas fiscais não aprova pagamentos. Dois perfis diferentes evitam que uma pessoa faça o ciclo inteiro e esconda uma fraude."), Mn("Perfil é um conjunto de permissões por função, com segregação de funções.")],
            ["si-16"] = [Mn("UPDATE em produção: faça um SELECT com o mesmo WHERE antes e tenha backup ou transação com ROLLBACK."), Er("Esquecer o WHERE. O UPDATE altera todas as linhas da tabela.")],
            ["si-17"] = [Mn("Índice acelera a leitura e pesa na escrita. É como um sumário que precisa ser atualizado."), Er("Criar índice em todas as colunas. Cada índice ocupa espaço e deixa INSERT e UPDATE mais lentos.")],
            ["si-18"] = [Mn("429 é Too Many Requests: vá mais devagar. Use espera crescente e respeite o Retry-After."), Er("Reenviar a requisição imediatamente, em laço. Isso aumenta o excesso e prolonga o bloqueio.")],
            ["si-19"] = [Ex("Em vez de alguém exportar os pedidos da loja e importar no ERP toda manhã, a API envia cada pedido assim que ele fecha, com registro das falhas."), Er("Achar que a API dispensa teste e monitoramento. Integrações também falham e precisam de alertas e logs.")],
            ["si-20"] = [Mn("Lentidão: olhe o banco (consultas lentas e bloqueios) e o servidor (CPU, memória e disco) no mesmo horário."), Er("Reiniciar o serviço sem coletar evidências. O reinício apaga o estado que mostraria a causa.")],

            // ===== Segurança =====
            ["se-01"] = [Mn("Link, urgência e pedido de senha formam a receita do phishing. Não clique, não informe e reporte."), Ex("O e-mail diz que sua conta expira em uma hora e pede a senha em um link. Você não clica e reporta ao canal da equipe de segurança.")],
            ["se-02"] = [Mn("Mídia encontrada não entra no PC. Entregue à TI ou à segurança."), Er("Conectar só para ver de quem é. É assim que o atacante espera que a isca funcione.")],
            ["se-03"] = [Ex("Uma falha em um navegador recebe a correção em um patch. Quem não atualiza continua vulnerável, mesmo com o conserto já publicado."), Mn("Patch é porta fechada: atualizar fecha falhas já conhecidas.")],
            ["se-04"] = [Mn("Ordem: isolar, preservar e acionar. Primeiro conter, depois entender."), Er("Formatar a máquina na hora e perder as evidências de como o malware entrou.")],
            ["se-05"] = [Ex("Mesmo que um e-mail malicioso passe pelo filtro, o antivírus da estação, a conta com poucos privilégios e o backup ainda limitam o estrago. São camadas."), Mn("Defesa em profundidade é como uma cebola: várias camadas, e nenhuma é a única.")],
            ["se-06"] = [Mn("Ransomware: desconecte da rede primeiro e depois acione o processo de incidente."), Er("Pagar o resgate por impulso. Não há garantia de recuperação, e a decisão cabe à gestão, pelo processo.")],
            ["se-07"] = [Ex("O cadeado do navegador em um site de banco indica TLS. O login viaja cifrado, e quem está no mesmo Wi-Fi não lê a senha."), Er("Achar que HTTPS significa que o site é confiável. Ele cifra a conexão, mas não garante que o dono do site seja honesto.")],
            ["se-08"] = [Ex("Alguém liga dizendo ser da diretoria e exige acesso remoto imediato. Você pede a validação pelo processo, recusa até confirmar e registra a tentativa."), Mn("Sem identidade validada, sem acesso. A pressa faz parte do golpe.")],
            ["se-09"] = [Mn("Sem log e sem hora certa não há linha do tempo. Preserve os logs e sincronize os relógios com NTP."), Ex("O firewall registra 14:02 e o servidor registra 14:17 para o mesmo evento. Com relógios diferentes, ninguém sabe a ordem real dos fatos.")],
            ["se-10"] = [Mn("Ciclo do NIST: preparar, detectar e analisar, conter, erradicar e recuperar, e aprender."), Er("Tratar o incidente só como contenção e esquecer a preparação antes e as lições aprendidas depois.")],
            ["se-11"] = [Ex("O firewall da empresa bloqueia o acesso de fora à porta de administração remota dos servidores e só permite a conexão pela VPN."), Mn("Firewall é o porteiro: as regras dizem quem entra e quem sai.")],
            ["se-12"] = [Mn("Domínio parecido, link estranho e urgência: três sinais de phishing."), Ex("Chega um e-mail de um domínio que troca a letra L pelo número 1 no nome da empresa, pedindo sua senha. O domínio parecido entrega o golpe.")],
            ["se-13"] = [Ex("Você vai pegar um café e aperta Win+L para bloquear o computador. Sem isso, alguém passa e envia um e-mail em seu nome."), Mn("Saiu da mesa, bloqueou a tela.")],
            ["se-14"] = [Mn("Vulnerabilidade é a brecha. Ameaça é quem pode usá-la."), Ex("Um servidor sem patch tem uma vulnerabilidade. O grupo de ransomware que explora essa falha é a ameaça.")],
            ["se-15"] = [Mn("Digitou a senha em phishing: trocar a senha, revogar sessões, verificar acessos e abrir incidente."), Er("Trocar só a senha e esquecer as sessões abertas. O invasor continua conectado.")],
            ["se-16"] = [Mn("Contra ransomware: backup offline e testado, patch em dia e privilégio mínimo."), Er("Desativar o antivírus porque deixa o computador lento. Isso remove uma camada de proteção.")],
            ["se-17"] = [Ex("Quem cadastra fornecedores não pode aprovar os pagamentos a eles. Para fraudar, seria preciso combinar entre duas pessoas."), Mn("Ninguém faz sozinho o processo inteiro: quem cria, quem aprova e quem paga são pessoas diferentes.")],
            ["se-18"] = [Mn("Pagamento fora do padrão: confirme por um segundo canal e exija dupla aprovação."), Ex("Um falso executivo manda e-mail pedindo transferência urgente para uma conta nova. O financeiro liga para o número oficial do executivo e exige a aprovação de um segundo responsável.")],
            ["se-19"] = [Mn("Lições aprendidas: corrija o processo, não procure o culpado."), Er("Encerrar o incidente sem revisão. As mesmas falhas voltam na próxima vez.")],
            ["se-20"] = [Mn("VPN segura: MFA mais verificação do dispositivo."), Er("Usar uma conta de VPN compartilhada. Ninguém sabe quem entrou, e não dá para revogar só um acesso.")],

            // ===== Backup e continuidade =====
            ["ba-01"] = [Mn("3-2-1: três cópias, dois tipos de mídia e uma cópia fora do local."), Ex("Os dados ficam no servidor, uma cópia vai para um NAS e outra para uma fita guardada em outra unidade. São três cópias, duas mídias e uma externa.")],
            ["ba-02"] = [Mn("Backup não testado é só esperança. Teste a restauração."), Er("Confiar no job concluído com sucesso sem nunca restaurar nada para conferir.")],
            ["ba-03"] = [Mn("Incremental copia só o que mudou desde o último backup de qualquer tipo, e a restauração é em cadeia."), Er("Esquecer que a restauração precisa do último completo mais todos os incrementais. Perder um elo quebra a cadeia.")],
            ["ba-04"] = [Mn("RPO é quanto dado posso perder (olha para trás). RTO é em quanto tempo volto (olha para frente)."), Ex("Se o RPO do ERP é de 1 hora, o backup precisa rodar ao menos de hora em hora. Se o RTO é de 4 horas, o serviço deve voltar em até 4 horas depois da falha.")],
            ["ba-05"] = [Mn("Diferencial é o completo mais o último diferencial."), Er("Achar que são necessários todos os diferenciais. Cada novo diferencial já contém o que mudou desde o completo.")],
            ["ba-06"] = [Ex("O log mostra falta de espaço no destino por duas noites seguidas. Você libera espaço, reexecuta o job e registra o incidente."), Er("Ignorar a falha porque existe um backup da semana passada. Cada noite sem backup é um dia de dados que pode ser perdido.")],
            ["ba-07"] = [Mn("Restaure em outro lugar, confira e depois devolva. Nunca sobrescreva às cegas."), Ex("O usuário apagou a planilha ontem. Você restaura a versão de ontem em uma pasta temporária, confirma que é a correta e só então copia ao destino.")],
            ["ba-08"] = [Mn("Backup bom é o que o ransomware não alcança: imutável ou offline, com credenciais separadas."), Er("Deixar o destino do backup montado como unidade de rede com acesso total. O ransomware criptografa a unidade junto.")],
            ["ba-09"] = [Mn("Plano de continuidade bom é plano testado. Sem teste, vira papel."), Ex("A empresa simula a queda do servidor principal duas vezes por ano, seguindo o plano, e ajusta o que não funcionou.")],
            ["ba-10"] = [Mn("Recuperação de desastres: inventário priorizado, RTO e RPO por sistema, responsáveis e testes."), Er("Depender de uma só pessoa que conhece a senha ou os passos. Se ela estiver ausente, a recuperação para.")],
            ["ba-11"] = [Mn("Completo é tudo, toda vez. Restaura fácil, mas ocupa mais espaço e tempo."), Ex("Todo domingo o backup copia a pasta inteira do servidor de arquivos, independentemente do que mudou.")],
            ["ba-12"] = [Ex("Um usuário apaga uma pasta por engano e você a recupera da cópia de ontem, no local original ou em um local alternativo."), Mn("Backup é a cópia. Restauração é a volta dela.")],
            ["ba-13"] = [Mn("A cópia externa protege de desastre local: incêndio, inundação e roubo."), Er("Guardar a cópia externa na sala ao lado do servidor. O mesmo incêndio atinge as duas.")],
            ["ba-14"] = [Mn("Diferencial restaura com duas peças: o completo e o último diferencial. Incremental restaura em cadeia."), Er("Dizer que o diferencial ocupa menos espaço que o incremental. Em geral ocorre o contrário: ele cresce a cada dia até o próximo completo.")],
            ["ba-15"] = [Mn("Teste de restauração que falha é um bom resultado: você descobriu o problema antes do desastre."), Er("Considerar o backup válido só pelo status do job, sem validar o conteúdo restaurado.")],
            ["ba-16"] = [Mn("O RPO nasce de duas perguntas: quanto dado posso perder e com que ritmo entram dados novos."), Ex("Se o ERP não pode perder duas horas de pedidos, o RPO precisa ser menor que isso, e o backup ou a replicação precisam ser mais frequentes.")],
            ["ba-17"] = [Er("Achar que sincronizar é fazer backup. A exclusão ou a criptografia por ransomware se replicam na nuvem."), Mn("A sincronização espelha o estado atual. O backup guarda versões do passado.")],
            ["ba-18"] = [Mn("Recupere por prioridade: primeiro o que sustenta os demais e o que o negócio mais precisa."), Ex("Depois da queda do datacenter, primeiro volta a rede, depois o diretório (login) e o banco do ERP, e só então os sistemas de menor impacto.")],
            ["ba-19"] = [Mn("Hot é quente: pronto e atualizado. Cold é frio: só espaço e infraestrutura."), Er("Achar que um hot site é só um espaço vazio. Ele já tem equipamentos e dados atualizados.")],
            ["ba-20"] = [Ex("Os documentos fiscais são guardados pelo prazo que a legislação exige e os logs comuns por um prazo menor, definido na política. Vencido o prazo, são apagados de forma definitiva."), Mn("Retenção: por quanto tempo guardar, por quê e como descartar quando vence.")],
        };
